//! Exact key-state fixtures generated by the pinned keripy reference.
//!
//! The pinned signify-ts reference never builds, validates or compares a key state, so the builder,
//! reader and comparison are verified against keripy. See `fixtures/key-state-keripy/README.md`.

use std::error::Error;

use keri_cesr::crypto::digest::Digest;
use keri_cesr::crypto::verifier::VerificationKey;
use keri_protocol::event::EventError;
use keri_protocol::event::config::ConfigurationTrait;
use keri_protocol::event::key_state::{
    ESTABLISHMENT_LABELS, FIELD_LABELS, KeyStateBuilder, KeyStateRecord, LatestEstablishment, StateComparison, compare,
};
use keri_protocol::event::kind::EventKind;
use keri_protocol::event::timestamp::Timestamp;
use keri_protocol::prefix::IdentifierPrefix;
use keri_protocol::said::Said;
use keri_protocol::serialization::{Sad, SadValue, SerializedEvent};
use keri_protocol::threshold::SigningThreshold;
use serde::Deserialize;

const REFERENCE_SHA: &str = "4ce4cc79e06653f77342be1bf604086b89b1f090";

#[derive(Debug, Deserialize)]
struct Fixture {
    schema_version: u8,
    upstream: String,
    reference_sha: String,
    reference_version: String,
    generated_on: String,
    sources: Vec<String>,
    timestamp: String,
    field_labels: Vec<String>,
    establishment_labels: Vec<String>,
    cases: Vec<RecordCase>,
    ksn_reply: ReplyCase,
    comparisons: Vec<ComparisonCase>,
    comparison_of_different_identifiers: MismatchCase,
    rejected_cases: Vec<RejectedCase>,
    reference_quirk_unreachable_ample_default: AmpleQuirk,
}

#[derive(Debug, Deserialize)]
struct RecordCase {
    name: String,
    inputs: Option<Inputs>,
    record_json: String,
}

#[derive(Debug, Deserialize)]
struct Inputs {
    identifier: String,
    sequence_number: u128,
    prior: String,
    said: String,
    first_seen: u128,
    latest_kind: String,
    keys: Vec<String>,
    signing_threshold: Option<String>,
    next_digests: Vec<String>,
    next_threshold: Option<String>,
    witness_threshold: Option<u32>,
    witnesses: Vec<String>,
    configuration: Vec<String>,
    establishment: EstablishmentInputs,
    delegator: Option<String>,
}

#[derive(Debug, Deserialize)]
struct EstablishmentInputs {
    sequence_number: u128,
    said: String,
    removed: Vec<String>,
    added: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct ReplyCase {
    route: String,
    raw: String,
    raw_hex: String,
}

#[derive(Debug, Deserialize)]
struct ComparisonCase {
    name: String,
    local: String,
    reported: String,
    state: String,
    sequence_number: u128,
    said: String,
}

#[derive(Debug, Deserialize)]
struct MismatchCase {
    local: String,
    reported: String,
    reference_error_category: String,
    reference_error_message: String,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct RejectedCase {
    name: String,
    inputs: Inputs,
    reference_error_category: String,
    reference_error_message: String,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct AmpleQuirk {
    witnesses: usize,
    keripy_default: u32,
    note: String,
}

fn fixture() -> Result<Fixture, Box<dyn Error>> {
    Ok(serde_json::from_str(include_str!(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/fixtures/key-state-keripy/v1.json"
    )))?)
}

fn decode_hex(input: &str) -> Result<Vec<u8>, Box<dyn Error>> {
    if !input.len().is_multiple_of(2) {
        return Err("odd-length hexadecimal fixture field".into());
    }
    (0..input.len())
        .step_by(2)
        .map(|index| {
            input
                .get(index..index + 2)
                .ok_or_else(|| Box::<dyn Error>::from("hexadecimal fixture slice out of range"))
                .and_then(|pair| u8::from_str_radix(pair, 16).map_err(Into::into))
        })
        .collect()
}

fn prefixes(texts: &[String]) -> Result<Vec<IdentifierPrefix>, Box<dyn Error>> {
    Ok(texts
        .iter()
        .map(|text| IdentifierPrefix::from_qb64(text))
        .collect::<Result<_, _>>()?)
}

/// Feeds the arguments keripy's `state` was given to the Rust builder.
fn builder(inputs: &Inputs, timestamp: &str) -> Result<KeyStateBuilder, Box<dyn Error>> {
    let establishment = LatestEstablishment::new(
        inputs.establishment.sequence_number,
        Said::from_qb64(&inputs.establishment.said)?,
    )
    .removed(prefixes(&inputs.establishment.removed)?)
    .added(prefixes(&inputs.establishment.added)?);
    let mut builder = KeyStateBuilder::new(
        IdentifierPrefix::from_qb64(&inputs.identifier)?,
        inputs.sequence_number,
        Said::from_qb64(&inputs.said)?,
        inputs.latest_kind.parse::<EventKind>()?,
        Timestamp::parse(timestamp)?,
        inputs
            .keys
            .iter()
            .map(|key| VerificationKey::from_qb64(key))
            .collect::<Result<_, _>>()?,
        establishment,
    )
    .first_seen(inputs.first_seen)
    .next_digests(
        inputs
            .next_digests
            .iter()
            .map(|digest| Digest::from_qb64(digest))
            .collect::<Result<_, _>>()?,
    )
    .witnesses(prefixes(&inputs.witnesses)?)
    .configuration(
        inputs
            .configuration
            .iter()
            .map(|entry| entry.parse::<ConfigurationTrait>())
            .collect::<Result<_, _>>()?,
    );
    if !inputs.prior.is_empty() {
        builder = builder.prior(Said::from_qb64(&inputs.prior)?);
    }
    if let Some(threshold) = &inputs.signing_threshold {
        builder = builder.signing_threshold(SigningThreshold::from_json(threshold)?);
    }
    if let Some(threshold) = &inputs.next_threshold {
        builder = builder.next_threshold(SigningThreshold::from_json(threshold)?);
    }
    if let Some(threshold) = inputs.witness_threshold {
        builder = builder.witness_threshold(threshold);
    }
    if let Some(delegator) = &inputs.delegator {
        builder = builder.delegator(IdentifierPrefix::from_qb64(delegator)?);
    }
    Ok(builder)
}

fn read(record_json: &str) -> Result<KeyStateRecord, Box<dyn Error>> {
    Ok(KeyStateRecord::from_sad(&Sad::from_json_bytes(
        record_json.as_bytes(),
    )?)?)
}

fn record_named(fixture: &Fixture, name: &str) -> Result<KeyStateRecord, Box<dyn Error>> {
    let case = fixture
        .cases
        .iter()
        .find(|case| case.name == name)
        .ok_or(format!("no case {name}"))?;
    read(&case.record_json)
}

#[test]
fn fixture_metadata_matches_the_pinned_keripy_reference() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.schema_version, 1);
    assert_eq!(fixture.upstream, "https://github.com/WebOfTrust/keripy.git");
    assert_eq!(fixture.reference_sha, REFERENCE_SHA);
    assert_eq!(fixture.reference_version, "1.3.6");
    assert_ne!(fixture.generated_on, "");
    assert_eq!(
        fixture.sources,
        [
            "src/keri/core/eventing.py",
            "src/keri/db/basing.py",
            "src/keri/app/watching.py"
        ]
    );
    assert_eq!(fixture.field_labels, FIELD_LABELS);
    assert_eq!(fixture.establishment_labels, ESTABLISHMENT_LABELS);
    Ok(())
}

#[test]
fn every_keripy_record_is_reproduced_byte_for_byte() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.cases.len(), 11);
    let mut built_count = 0;
    for case in &fixture.cases {
        let read_back = read(&case.record_json)?;
        assert_eq!(
            read_back.to_sad()?.to_json_bytes()?,
            case.record_json.as_bytes(),
            "case {} does not round trip",
            case.name
        );
        if let Some(inputs) = &case.inputs {
            let built = builder(inputs, &fixture.timestamp)?.build()?;
            assert_eq!(
                built.to_sad()?.to_json_bytes()?,
                case.record_json.as_bytes(),
                "case {} built differently",
                case.name
            );
            assert_eq!(built, read_back, "case {} reads back differently", case.name);
            built_count += 1;
        }
    }
    assert_eq!(built_count, 9);
    Ok(())
}

#[test]
fn a_ksn_reply_carries_the_record_keripy_built() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let reply = &fixture.ksn_reply;
    assert_eq!(decode_hex(&reply.raw_hex)?, reply.raw.as_bytes());
    let message = SerializedEvent::parse(reply.raw.as_bytes())?;
    assert_eq!(message.sad().get_text("t"), Some("rpy"));
    assert_eq!(message.sad().get_text("r"), Some(reply.route.as_str()));
    let block = message
        .sad()
        .get("a")
        .and_then(SadValue::as_map)
        .ok_or("reply has no a block")?;
    let record = KeyStateRecord::from_sad(block)?;
    assert_eq!(record, record_named(&fixture, "interaction_after_rotation")?);
    assert_eq!(record.latest_kind(), EventKind::Interaction);
    assert_eq!(record.establishment().sequence_number(), 1);
    assert_eq!(record.establishment().witnesses_removed().len(), 1);
    assert_eq!(record.establishment().witnesses_added().len(), 1);
    Ok(())
}

#[test]
fn comparisons_match_keripy_diff_state() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.comparisons.len(), 4);
    for case in &fixture.comparisons {
        let local = record_named(&fixture, &case.local)?;
        let reported = record_named(&fixture, &case.reported)?;
        let difference = compare(&local, &reported)?;
        let expected = match case.state.as_str() {
            "even" => StateComparison::Even,
            "ahead" => StateComparison::Ahead,
            "behind" => StateComparison::Behind,
            "duplicitous" => StateComparison::Duplicitous,
            other => return Err(format!("unknown keripy state {other}").into()),
        };
        assert_eq!(difference.comparison(), expected, "comparison {}", case.name);
        assert_eq!(
            difference.sequence_number(),
            case.sequence_number,
            "comparison {}",
            case.name
        );
        assert_eq!(difference.said().qb64()?, case.said, "comparison {}", case.name);
    }

    let mismatch = &fixture.comparison_of_different_identifiers;
    assert_eq!(mismatch.reference_error_category, "ValueError");
    assert_ne!(mismatch.reference_error_message, "");
    assert_eq!(mismatch.rust_error_category, "IdentifierMismatch");
    let local = record_named(&fixture, &mismatch.local)?;
    let reported = record_named(&fixture, &mismatch.reported)?;
    assert!(matches!(
        compare(&local, &reported),
        Err(EventError::IdentifierMismatch)
    ));
    Ok(())
}

#[test]
fn keripy_rejections_map_to_stable_rust_error_categories() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.rejected_cases.len(), 11);
    for case in &fixture.rejected_cases {
        assert_eq!(
            case.reference_error_category, "ValueError",
            "rejected case {}",
            case.name
        );
        assert_ne!(case.reference_error_message, "");
        let Err(error) = builder(&case.inputs, &fixture.timestamp)?.build() else {
            return Err(format!("rejected case {} was built", case.name).into());
        };
        let matches = match case.rust_error_category.as_str() {
            "InvalidLatestEventKind" => matches!(error, EventError::InvalidLatestEventKind { .. }),
            "SigningThresholdIsZero" => matches!(error, EventError::SigningThresholdIsZero),
            "SigningThresholdExceedsKeys" => matches!(error, EventError::SigningThresholdExceedsKeys { .. }),
            "NextThresholdExceedsDigests" => matches!(error, EventError::NextThresholdExceedsDigests { .. }),
            "DuplicateWitness" => matches!(error, EventError::DuplicateWitness { .. }),
            "InvalidWitnessThreshold" => matches!(error, EventError::InvalidWitnessThreshold { .. }),
            "ConflictingWitnessLists" => matches!(error, EventError::ConflictingWitnessLists { .. }),
            other => return Err(format!("unknown rust error category {other}").into()),
        };
        assert!(matches, "rejected case {} produced {error:?}", case.name);
    }
    Ok(())
}

#[test]
fn the_reachable_witness_threshold_default_is_reproduced() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let quirk = &fixture.reference_quirk_unreachable_ample_default;
    assert_ne!(quirk.note, "");
    let record = record_named(&fixture, "inception_default_witness_threshold")?;
    assert_eq!(record.witnesses().len(), quirk.witnesses);
    assert_eq!(record.witness_threshold(), quirk.keripy_default);
    assert_eq!(quirk.keripy_default, 2);
    Ok(())
}
